import { useState } from 'react';
import './ChipBar.css';

export interface ChipBarProps {
  options: string[];
}

// ChipBar owns only visual pressed state. Filtering the grid is a separate
// concern — a parent will wire onSelect when that feature is built.
export function ChipBar({ options }: ChipBarProps): JSX.Element {
  const [pressed, setPressed] = useState<string | null>(null);

  function handleClick(option: string): void {
    setPressed(prev => (prev === option ? null : option));
  }

  return (
    <div className="chip-bar" role="toolbar">
      {options.map(option => (
        <button
          key={option}
          className="chip-bar-chip"
          aria-pressed={pressed === option}
          onClick={() => handleClick(option)}
          type="button"
        >
          {option}
        </button>
      ))}
    </div>
  );
}
